/// The close reason text sent with each close code (`CLOSE_REASONS`).
pub fn close_reason(code: u16) -> ::std::option::Option<&'static str> {
    match code {
        4000 => Some("replaced by a newer connection"),
        4001 => Some("machine revoked"),
        4003 => Some("unauthorized"),
        4005 => {
            Some("protocol version not supported: update the daemon (re-run the install command)")
        }
        _ => None,
    }
}
